1254		// Make fd/rg available in <agentDir>/bin BEFORE the TUI's init() looks
1255		// for them. The canonical agent directory is shared with the Pi CLI.
1256		await ensureRuntimeTools(agentDir);
1257	
1258		const extensionUri = extensionContext?.extensionUri;
1259		const extensionDir = extensionUri
1260			? vscode.Uri.joinPath(extensionUri, "resources", "extensions")
1261			: undefined;
1262	
1263		// Build all resource paths inside the runtime factory. The SDK may invoke this
1264		// factory for more than one new session; each session must see current settings
1265		// and bundled-resource toggles rather than activation-time snapshots.
1266		const createRuntime: any = async (opts: any) => {
1267			const settingsManager = pi.SettingsManager.create(opts.cwd, agentDir);
1268			const resourcePaths = buildPiRuntimeResourcePaths(
1269				extensionDir?.fsPath ?? "",
1270				agentDir,
1271				readJsonFile(getSettingsPath()) ?? {},
1272			);
1273			const bundledExtensions = resourcePaths.bundledExtensionPaths.filter((p) =>
1274				fs.existsSync(p),
1275			);
1276			const bundledThemes = resourcePaths.bundledThemePaths.filter((p) =>
1277				fs.existsSync(p),
1278			);
1279			if (fs.existsSync(resourcePaths.rpivTodoPath)) {
1280				bundledExtensions.push(resourcePaths.rpivTodoPath);
1281			} else {
1282				console.warn(
1283					"[CodePi] rpiv-todo extension not found at",
1284					resourcePaths.rpivTodoPath,
1285					"— no todo tool will be available to the agent.",
1286				);
1287			}
1288			const bundledThemeEnabled = bundledThemes.length > 0;
1289			const loaderOptions = buildPiResourceLoaderOptions(opts.cwd, agentDir, {
1290				...resourcePaths,
1291				bundledExtensionPaths: bundledExtensions,
1292				bundledThemePaths: bundledThemes,
1293			});
1294			const loader = new pi.DefaultResourceLoader({
1295				...loaderOptions,
1296				settingsManager,
1297				extensionsOverride: (base: any) => {
1298					const bundled = new Set(bundledExtensions);
1299					return {
1300						...base,
1301						extensions: [
1302							...base.extensions.filter(
1303								(extension: any) =>
1304									!bundled.has(extension.resolvedPath ?? extension.path),
1305							),
1306							...base.extensions.filter((extension: any) =>
1307								bundled.has(extension.resolvedPath ?? extension.path),
1308							),
1309						],
1310					};
1311				},
1312			});
1313			await loader.reload();
1314			applyImplicitBundledTheme(settingsManager, bundledThemeEnabled);
1315			const result = await pi.createAgentSession({
1316				resourceLoader: loader,
1317				settingsManager,
1318				cwd: opts.cwd,
1319				agentDir,
1320				noTools: "builtin",
1321				customTools: createVscodeTools(state.review),
1322				sessionManager: opts.sessionManager,
1323				sessionStartEvent: { type: "session_start", reason: "startup" },
1324			});
1325			installImplicitBundledThemeReload(result.session, settingsManager, () =>
1326				buildPiRuntimeResourcePaths(
1327					extensionDir?.fsPath ?? "",
1328					agentDir,
1329					readJsonFile(getSettingsPath()) ?? {},
1330				).bundledThemePaths.some((p) => fs.existsSync(p)),
1331			);
1332			return result;
1333		};
1334	
1335		const runtime = await pi.createAgentSessionRuntime(createRuntime, {
1336			cwd: workspaceRoot,
1337			agentDir,
1338			sessionManager: state.sessionManager,
1339		});
1340		state.runtime = runtime;
1341	
1342		state.tui = new pi.InteractiveMode(runtime, {
1343			terminal: state.pty,
1344			verbose: true,
1345		});
1346	
1347		state.isBackendReady = true;
1348		state.isBusy = true;
1349		treeProvider?.refresh();
1350	
