1355				state.panel.dispose();
1356			})
1357			.catch((err: Error) => {
1358				console.error("[CodePi] TUI exited with error:", err);
1359				void vscode.window.showErrorMessage(
1360					`CodePi TUI error: ${err.message || String(err)}`,
1361				);
1362			});
