  95		private async sendData(): Promise<void> {
  96			const settingsPath = getSettingsPathForAgent(this.agentDir);
  97			const settings = readJsonFile<Record<string, unknown>>(settingsPath) ?? {};
  98			const sdk = await getSdk();
  99			const cwd =
 100				vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? this.agentDir;
 101			const settingsManager = sdk.SettingsManager.create(cwd, this.agentDir);
 102			const packageManager = new sdk.DefaultPackageManager({
 103				cwd,
 104				agentDir: this.agentDir,
 105				settingsManager,
 106			});
 107			const packages = mapConfiguredPackageStatus(
 108				packageManager.listConfiguredPackages(),
 109			);
