 120		private async setBundledResource(
 121			id: DashboardData["bundledResources"][number]["id"],
 122			enabled: boolean,
 123		): Promise<void> {
 124			const settingsPath = getSettingsPathForAgent(this.agentDir);
 125			if (!isBundledResourceId(id)) {
 126				throw new Error(`Unknown bundled resource: ${id}`);
 127			}
 128			const settings = readJsonFile<Record<string, unknown>>(settingsPath) ?? {};
 129			const current = readBundledResourceConfig(settings);
 130			const next: BundledResourceConfig = {
 131				bundledExtensions: { ...current.bundledExtensions },
 132				bundledThemes: { ...current.bundledThemes },
 133			};
 134			if (id === "nebula-pulse") next.bundledThemes["nebula-pulse"] = enabled;
 135			else next.bundledExtensions[id] = enabled;
 136			updateBundledResourceConfig(settingsPath, next);
 137			this.onConfigSaved();
 138			this.post({ command: "settings:saved", ok: true, resource: id });
 139			await this.sendData();
 140		}
