 142		private async openFile(file: "settings" | "models" | "auth"): Promise<void> {
 143			const filePath = ensurePiJsonFileInDir(this.agentDir, file);
 144			const document = await vscode.workspace.openTextDocument(
 145				vscode.Uri.file(filePath),
 146			);
 147			await vscode.window.showTextDocument(document, { preview: false });
 148			this.post({ command: "settings:opened", file, path: filePath });
 149		}
 150	}
