 164	function buildSettingsHtml(
 165		extensionUri: vscode.Uri,
 166		webview: vscode.Webview,
 167	): string {
 168		const distUri = vscode.Uri.joinPath(extensionUri, "webview-ui", "dist");
 169		const scriptUri = webview.asWebviewUri(
 170			vscode.Uri.joinPath(distUri, "assets", "settings.js"),
 171		);
 172		const styleUri = webview.asWebviewUri(
 173			vscode.Uri.joinPath(distUri, "assets", "index.css"),
 174		);
 175		const nonce = getNonce();
 176		return /* html */ `<!DOCTYPE html>
 177	<html lang="en">
 178	<head>
 179	  <meta charset="UTF-8" />
 180	  <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src ${webview.cspSource} 'unsafe-inline'; script-src ${webview.cspSource} 'nonce-${nonce}';" />
1235				d.dispose();
1236			} catch {
1237				/* ignore */
1238			}
1239		}
1240	}
1241	
1242	// ── Backend Setup ────────────────────────────────────────────
1243	
1244	async function startTuiBackend(state: SessionState): Promise<void> {
1245		const pi = await getPi();
1246		const workspaceRoot = getWorkspaceRoot();
1247		const agentDir = getCanonicalAgentDir();
1248	
1249		// Make fd/rg available in <agentDir>/bin BEFORE the TUI's init() looks
1250		// for them. The canonical agent directory is shared with the Pi CLI.
1251		await ensureRuntimeTools(agentDir);
1252	
1253		const extensionUri = extensionContext?.extensionUri;
1254		const extensionDir = extensionUri
1255			? vscode.Uri.joinPath(extensionUri, "resources", "extensions")
1256			: undefined;
1257	
1258		// Build all resource paths inside the runtime factory. The SDK may invoke this
1259		// factory for more than one new session; each session must see current settings
1260		// and bundled-resource toggles rather than activation-time snapshots.
1261		const createRuntime: any = async (opts: any) => {
1262			const settingsManager = pi.SettingsManager.create(opts.cwd, agentDir);
1263			const resourcePaths = buildPiRuntimeResourcePaths(
1264				extensionDir?.fsPath ?? "",
1265				agentDir,
1266				readJsonFile(getSettingsPath()) ?? {},
1267			);
1268			const bundledExtensions = resourcePaths.bundledExtensionPaths.filter((p) =>
1269				fs.existsSync(p),
1270			);
1271			const bundledThemes = resourcePaths.bundledThemePaths.filter((p) =>
1272				fs.existsSync(p),
1273			);
1274			if (fs.existsSync(resourcePaths.rpivTodoPath)) {
1275				bundledExtensions.push(resourcePaths.rpivTodoPath);
1276			} else {
1277				console.warn(
1278					"[CodePi] rpiv-todo extension not found at",
1279					resourcePaths.rpivTodoPath,
1280					"— no todo tool will be available to the agent.",
1281				);
1282			}
1283			const bundledThemeEnabled = bundledThemes.length > 0;
1284			const loaderOptions = buildPiResourceLoaderOptions(opts.cwd, agentDir, {
1285				...resourcePaths,
1286				bundledExtensionPaths: bundledExtensions,
1287				bundledThemePaths: bundledThemes,
1288			});
1289			const loader = new pi.DefaultResourceLoader({
1290				...loaderOptions,
1291				settingsManager,
1292				extensionsOverride: (base: any) => {
1293					const bundled = new Set(bundledExtensions);
1294					return {
1295						...base,
1296						extensions: [
1297							...base.extensions.filter(
1298								(extension: any) =>
1299									!bundled.has(extension.resolvedPath ?? extension.path),
1300							),
1301							...base.extensions.filter((extension: any) =>
1302								bundled.has(extension.resolvedPath ?? extension.path),
1303							),
1304						],
1305					};
1306				},
1307			});
1308			await loader.reload();
1309			applyImplicitBundledTheme(settingsManager, bundledThemeEnabled);
1310			const result = await pi.createAgentSession({
1311				resourceLoader: loader,
1312				settingsManager,
1313				cwd: opts.cwd,
1314				agentDir,
1315				noTools: "builtin",
1316				customTools: createVscodeTools(state.review),
1317				sessionManager: opts.sessionManager,
1318				sessionStartEvent: { type: "session_start", reason: "startup" },
1319			});
1320			installImplicitBundledThemeReload(result.session, settingsManager, () =>
1321				buildPiRuntimeResourcePaths(
1322					extensionDir?.fsPath ?? "",
1323					agentDir,
1324					readJsonFile(getSettingsPath()) ?? {},
1325				).bundledThemePaths.some((p) => fs.existsSync(p)),
1326			);
1327			return result;
1328		};
1329	
1330		const runtime = await pi.createAgentSessionRuntime(createRuntime, {
1331			cwd: workspaceRoot,
1332			agentDir,
1333			sessionManager: state.sessionManager,
1334		});
1335		state.runtime = runtime;
1336	
1337		state.tui = new pi.InteractiveMode(runtime, {
1338			terminal: state.pty,
1339			verbose: true,
1340		});
1341	
1342		state.isBackendReady = true;
1343		state.isBusy = true;
1344		treeProvider?.refresh();
1345	
1346		// run() resolves when the TUI exits (e.g. /quit) → close the panel tab.
1347		void state.tui
1348			.run()
1349			.then(() => {
1350				state.panel.dispose();
1351			})
1352			.catch((err: Error) => {
1353				console.error("[CodePi] TUI exited with error:", err);
1354				void vscode.window.showErrorMessage(
1355					`CodePi TUI error: ${err.message || String(err)}`,
1356				);
1357			});
1358	}
1359	
1360	// ── Pending-edit tab dots (Copilot-style) ────────────────────

